parameters.jsCode:
// Extract raw text from Gemini response structure
let rawText = $input.item.json.candidates[0].content.parts[0].text;

// Clean potential markdown blocks if Gemini includes them anyway
rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

const parsedAI = JSON.parse(rawText);

// Safely pull raw data from Google Sheets Trigger
const rawSheetData = $('Google Sheets Trigger').first().json;

// Normalize all keys by trimming extra spaces around column names
const cleanSheetData = {};
for (const key in rawSheetData) {
  cleanSheetData[key.trim()] = rawSheetData[key];
}

return {
  json: {
    ...cleanSheetData,
    aiPriority: parsedAI.priority,
    aiCategory: parsedAI.category,
    aiOwner: parsedAI.suggestedOwner,
    ainotes: parsedAI.notes
  }
};

